const body = $json.body ?? {};
const headers = $json.headers ?? {};
const errors = [];

function header(name) {
  const value = headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()];
  return typeof value === 'string' ? value.trim() : '';
}

function isIpv4(value) {
  const parts = value.split('.');
  return parts.length === 4 && parts.every((part) => {
    if (!/^\d{1,3}$/.test(part)) return false;
    const number = Number(part);
    return number >= 0 && number <= 255 && String(number) === String(Number(part));
  });
}

function isIpv6(value) {
  let ip = value.toLowerCase();
  if (ip.startsWith('::ffff:') && ip.includes('.')) return isIpv4(ip.slice(7));
  if (!/^[0-9a-f:]+$/.test(ip) || ip.includes(':::')) return false;
  const doubles = (ip.match(/::/g) ?? []).length;
  if (doubles > 1) return false;
  const parts = ip.split(':');
  const groups = parts.filter(Boolean);
  if (!groups.every((part) => part.length <= 4 && /^[0-9a-f]+$/.test(part))) return false;
  return ip.includes('::') ? groups.length < 8 : groups.length === 8;
}

function clientIp() {
  const candidate =
    header('cf-connecting-ip') ||
    header('x-real-ip') ||
    header('x-forwarded-for').split(',')[0]?.trim() ||
    '';
  const value = candidate.replace(/^\[|\]$/g, '');
  return isIpv4(value) || isIpv6(value) ? value : '';
}

const ip = clientIp();
if (!ip) errors.push('IP-Adresse fehlt oder ist ungültig.');

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Request Body muss ein JSON-Objekt sein.');
}

const allowedUnits = ['g', 'ml', 'piece'];
const difficulties = ['quick', 'medium', 'complex'];
const cuisines = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const diets = ['vegetarian', 'vegan', 'keto', 'none'];

if (body.schemaVersion !== 2) errors.push('schemaVersion muss 2 sein.');
if (typeof body.clientRequestId !== 'string' || !body.clientRequestId.trim()) {
  errors.push('clientRequestId fehlt.');
}
if (!Number.isInteger(body.servings) || body.servings < 1 || body.servings > 12) {
  errors.push('servings muss zwischen 1 und 12 liegen.');
}
if (!Number.isInteger(body.cookCount) || body.cookCount < 1 || body.cookCount > 3) {
  errors.push('cookCount muss zwischen 1 und 3 liegen.');
}
if (!body.preferences || typeof body.preferences !== 'object' || Array.isArray(body.preferences)) {
  errors.push('preferences fehlen.');
} else {
  if (!difficulties.includes(body.preferences.difficulty)) errors.push('difficulty ist ungültig.');
  if (!cuisines.includes(body.preferences.cuisine)) errors.push('cuisine ist ungültig.');
  if (!diets.includes(body.preferences.diet)) errors.push('diet ist ungültig.');
}
if (!Array.isArray(body.ingredients) || body.ingredients.length < 1) {
  errors.push('Mindestens eine Zutat ist erforderlich.');
} else {
  const ids = new Set();
  body.ingredients.forEach((ingredient, index) => {
    if (!ingredient || typeof ingredient !== 'object' || Array.isArray(ingredient)) {
      errors.push(`Zutat ${index + 1} ist ungültig.`);
      return;
    }
    if (typeof ingredient.id !== 'string' || !ingredient.id.trim() || ids.has(ingredient.id)) {
      errors.push(`Zutat ${index + 1} benötigt eine eindeutige ID.`);
    } else ids.add(ingredient.id);
    if (typeof ingredient.name !== 'string' || !ingredient.name.trim()) {
      errors.push(`Zutat ${index + 1} benötigt einen Namen.`);
    }
    if (typeof ingredient.amount !== 'number' || !Number.isFinite(ingredient.amount) || ingredient.amount <= 0) {
      errors.push(`Zutat ${index + 1} benötigt eine positive Menge.`);
    }
    if (!allowedUnits.includes(ingredient.unit)) {
      errors.push(`Zutat ${index + 1} hat eine ungültige Einheit.`);
    }
  });
}

return [{
  json: {
    valid: errors.length === 0,
    clientIp: ip || null,

    clientIpKey: ip
      ? ip.replace(/[^0-9a-zA-Z]/g, '_')
      : null,

    request: body,

    errorCode:
      errors.length
        ? 'invalid_request'
        : null,

    errorMessage:
      errors.length
        ? errors.join(' ')
        : null,
  },
}];

